import sys

def max_digit_sum(x):
    x_str = str(x)
    n = len(x_str)
    result = [0] * n

    # Set the first digit
    if int(x_str[0]) > 1:
        result[0] = 9
    else:
        result[0] = int(x_str[0])

    # Fill the rest of the digits
    for i in range(1, n):
        if result[i-1] == 9:
            result[i] = 9
        else:
            result[i] = min(int(x_str[i]), 9)

    # Convert the result list back to an integer
    return int(''.join(map(str, result)))

